// Séjours et mobilités : démonstration locale, sans réservation distante.
const stayCatalog=[
{id:'luxe',name:'La maison en L',type:'Maison en L',capacity:4,night:145,units:2,area:'Deux containers & terrasse',tag:'La signature du Domaine',desc:'Deux ailes habillées de bois, une terrasse dans le creux du L et une pergola pour vivre dehors.',amenities:['2 chambres','Cuisine','Terrasse privative','Salle d’eau'],art:'luxe'},
{id:'cabane',name:'La cabane des sous-bois',type:'Cabane',capacity:2,night:85,units:2,area:'Un cocon tout en bois',tag:'Nature & calme',desc:'Une cabane de plain-pied, un intérieur chaleureux et une petite terrasse ouverte sur le jardin.',amenities:['1 chambre','Coin cuisine','Terrasse','Salle d’eau'],art:'cabane'},
{id:'perchee',name:'Le refuge perché',type:'Cabane perchée',capacity:2,night:110,units:1,area:'Une escapade en hauteur',tag:'Une autre perspective',desc:'Un refuge sur pilotis, accessible par un escalier, pour profiter de la canopée et du paysage.',amenities:['1 lit double','Terrasse en hauteur','Escalier','Salle d’eau'],art:'perchee'},
{id:'container',name:'Le container jardin',type:'Container',capacity:2,night:75,units:3,area:'Compact & connecté au jardin',tag:'L’essentiel, bien pensé',desc:'Un container aménagé avec une baie sur le jardin, un espace de vie compact et une terrasse.',amenities:['1 lit double','Kitchenette','Terrasse','Salle d’eau'],art:'container'},
{id:'tiny',name:'La tiny house du verger',type:'Tiny house',capacity:3,night:95,units:1,area:'Petite maison, grand horizon',tag:'À l’orée du verger',desc:'Une petite maison en bois, un couchage en mezzanine et un espace de séjour ouvert sur les arbres.',amenities:['Mezzanine','3 couchages','Cuisine','Terrasse'],art:'tiny'},
{id:'lodge',name:'Le lodge des jardins',type:'Lodge',capacity:4,night:90,units:2,area:'L’esprit du camping, le confort en plus',tag:'Vivre au grand air',desc:'Un lodge en toile sur plancher bois, avec une terrasse couverte et deux espaces de couchage.',amenities:['2 espaces nuit','Coin repas','Terrasse couverte','Sanitaires communs'],art:'lodge'}];
const bikeCatalog=[{id:'ville',name:'Vélo de ville',count:2,rate:3,desc:'Pour les chemins aménagés et les petites courses.',icon:'ville'},{id:'vtt',name:'VTT',count:2,rate:4,desc:'Pour explorer les chemins adaptés autour du Domaine.',icon:'vtt'},{id:'electrique',name:'Vélo électrique',count:1,rate:6,desc:'Une assistance pour les balades et les dénivelés.',icon:'electrique'},{id:'cargo',name:'Vélo cargo',count:1,rate:7,desc:'Pour transporter un panier ou des affaires.',icon:'cargo'}];
function travelInit(){state.staysV7??=[];state.bikesV7??=[]}
travelInit();save();
function datePlus(s,n){return new Date(Date.parse(s+'T12:00:00Z')+n*86400000).toISOString().slice(0,10)}
let staySearch={arrival:datePlus(nowDate(),7),departure:datePlus(nowDate(),9),guests:2,type:'Tous'};
let bikeSearch={date:datePlus(nowDate(),1),start:'09:00',end:'11:00'};
const dateValid=s=>/^\d{4}-\d{2}-\d{2}$/.test(s)&&Number.isFinite(Date.parse(s+'T12:00:00Z'))&&new Date(s+'T12:00:00Z').toISOString().slice(0,10)===s;
const nights=(a,b)=>Math.round((Date.parse(b+'T12:00:00Z')-Date.parse(a+'T12:00:00Z'))/86400000);
function stayError(s){if(!dateValid(s.arrival)||!dateValid(s.departure))return 'Choisissez des dates valides.';if(s.arrival<nowDate())return 'Choisissez une arrivée à partir d’aujourd’hui.';const n=nights(s.arrival,s.departure);if(n<1||n>30)return 'Choisissez un séjour de 1 à 30 nuits.';if(!Number.isInteger(Number(s.guests))||s.guests<1||s.guests>4)return 'Choisissez de 1 à 4 voyageurs.';return ''}
const overlaps=(a,b,c,d)=>a<d&&c<b;
function stayUnit(p,s){travelInit();if(stayError(s)||s.guests>p.capacity)return null;for(let u=1;u<=p.units;u++)if(!state.staysV7.some(b=>b.habitat===p.id&&b.unit===u&&b.status!=='annule'&&overlaps(s.arrival,s.departure,b.arrival,b.departure)))return u;return null}
function stayQuote(p,s){const subtotal=Math.round(p.night*nights(s.arrival,s.departure)*100)/100;return {nights:nights(s.arrival,s.departure),subtotal,fee:20,total:subtotal+20}}
function travelId(prefix){return prefix+'-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,6).toUpperCase()}
function habitatArt(kind){const wood=kind==='container'?'#748a6a':'#b58b60';const bg=kind==='lodge'?'#ebe4cf':kind==='perchee'?'#d6e3d5':'#e4e9da';let object='';
if(kind==='luxe')object='<path d="m98 117 85-42 126 62-31 17-56-29-54 27Z" fill="#a88560"/><path d="m98 117 70 35v37l-70-35Z" fill="#b58c60"/><path d="m168 152 54-27v37l-54 27Z" fill="#d2b48b"/><path d="m222 125 56 29v37l-56-29Z" fill="#b58c60"/><path d="m278 154 31-17v37l-31 17Z" fill="#8c714f"/><path d="m165 159 56-28 47 26-57 29Z" fill="#dfc6a0"/><path d="m108 130 46 23v24l-46-23Z" fill="#b0ccc2"/><path d="m229 138 39 20v23l-39-20Z" fill="#b0ccc2"/>';
else if(kind==='lodge')object='<path d="m108 177 79-120 92 133Z" fill="#b7b395"/><path d="m187 57 69-34 91 132-68 35Z" fill="#ece2c6"/><path d="m155 180 31-80 49 86Z" fill="#605e4b"/><path d="m111 182 79-43 125 67-80 43Z" fill="#bb9870"/>';
else {let lift=kind==='perchee'?33:0;object=`${lift?'<path d="M117 183v44m72-9v37m77-80v45" stroke="#8a7254" stroke-width="6"/><path d="m268 192 40 42m-32-32 27-14m-19 22 27-14m-19 22 27-14" stroke="#8a7254" stroke-width="4"/>':''}<g transform="translate(0 ${-lift})"><path d="m104 140 79-42 100 51-80 43Z" fill="#3c574c"/><path d="m104 140 99 52v48l-99-52Z" fill="${wood}"/><path d="m203 192 80-43v48l-80 43Z" fill="#8b7858"/><path d="m117 153 58 30v29l-58-30Z" fill="#bdd4c3"/><path d="m223 190 35-19v32l-35 19Z" fill="#c8d2b9"/>${kind==='cabane'||kind==='tiny'||kind==='perchee'?'<path d="m95 137 48-58 69 110Z" fill="#53715e"/><path d="m143 79 77-40 69 109-77 41Z" fill="#769078"/>':''}<path d="m105 189 97 51 83-44 21 12-104 56-120-63Z" fill="#d2b78d"/></g>`}
return `<svg viewBox="0 0 400 280" role="img" aria-label="Illustration ${esc(stayCatalog.find(p=>p.art===kind)?.type||'habitat')}"><rect width="400" height="280" fill="${bg}"/><circle cx="310" cy="55" r="31" fill="#fff6d0"/><ellipse cx="203" cy="233" rx="150" ry="27" fill="#b4c39b" opacity=".5"/><path d="M40 208v-88m310 97v-90" stroke="#938363" stroke-width="7"/><path d="m40 66-31 87h62Zm310 7-33 93h66Z" fill="#8fa87a"/><path d="m40 49-23 70h46Zm310 5-23 73h46Z" fill="#a4ba8c"/>${object}<path d="M60 232q10-37 20 0m237-2q10-40 20 0" fill="#819965"/></svg>`}
function bikeArt(kind){return `<svg viewBox="0 0 320 170" role="img" aria-label="Illustration ${esc(bikeCatalog.find(b=>b.id===kind)?.name||'vélo')}"><rect width="320" height="170" fill="#e8edde"/><circle cx="80" cy="116" r="34" fill="#f9f8ef" stroke="#536259" stroke-width="5"/><circle cx="240" cy="116" r="34" fill="#f9f8ef" stroke="#536259" stroke-width="5"/><g stroke="${kind==='electrique'?'#bb8d58':'#6a8b6c'}" stroke-width="6" fill="none" stroke-linejoin="round"><path d="m80 116 48-64 42 64H80l38-47 93 0 29 47m-70 0 40-60m-82-4-5-12m82 29-8-27h18"/></g><path d="M111 39h29" stroke="#3b5044" stroke-width="7" stroke-linecap="round"/>${kind==='cargo'?'<path d="M27 64h76l-8 33H35Z" fill="#b5966d"/>':kind==='electrique'?'<rect x="148" y="73" width="13" height="30" rx="3" fill="#45664f"/>':''}<path d="m164 116 12 12 13-2" stroke="#3b5044" stroke-width="4" fill="none"/></svg>`}
function staySearchForm(){return `<form class="travel-search" onsubmit="event.preventDefault();searchStays(this)"><div><label for="stay-arrival">Arrivée</label><input id="stay-arrival" name="arrival" type="date" min="${nowDate()}" required value="${staySearch.arrival}"></div><div><label for="stay-departure">Départ</label><input id="stay-departure" name="departure" type="date" min="${datePlus(staySearch.arrival,1)}" required value="${staySearch.departure}"></div><div><label for="stay-guests">Voyageurs</label><select id="stay-guests" name="guests">${[1,2,3,4].map(n=>`<option value="${n}" ${staySearch.guests===n?'selected':''}>${n} personne${n>1?'s':''}</option>`).join('')}</select></div><button class="btn">Rechercher un séjour ↗</button></form>`}
function searchStays(f){const s={arrival:f.arrival.value,departure:f.departure.value,guests:Number(f.guests.value),type:staySearch.type};const err=stayError(s);if(err){toast(err);return}staySearch=s;if(location.hash!=='#sejours')location.hash='#sejours';else render()}
function stayCards(items){return items.map(p=>{const available=stayUnit(p,staySearch)!==null;return `<article class="stay-card"><button class="stay-art" onclick="stayDetail('${p.id}')">${p.id==='luxe'?'<img src="assets/maison-l-bois-reference.webp" alt="Maison en L avec terrasse en bois">':habitatArt(p.art)}<span>${p.tag}</span></button><div class="stay-body"><small>${p.type} · ${p.capacity} personnes maximum</small><h3><button onclick="stayDetail('${p.id}')">${p.name}</button></h3><p>${p.area}</p><div class="stay-amenities">${p.amenities.slice(0,3).map(a=>`<span>${a}</span>`).join('')}</div><div class="stay-price"><div><b>${money(p.night)}</b><small> / nuit fictive</small><span class="${available?'available':'unavailable'}">${available?'Disponible pour vos dates':'Indisponible pour vos critères'}</span></div><button class="btn light" onclick="stayDetail('${p.id}')">Découvrir ↗</button></div></div></article>`}).join('')}
function staysView(){travelInit();const list=stayCatalog.filter(p=>staySearch.type==='Tous'||p.type===staySearch.type);return heading('Un séjour à votre rythme.','Choisissez un habitat et découvrez une autre façon de vivre au Domaine.',`<a class="btn light" href="#reservations">Mes réservations ↗</a>`)+`<div class="travel-demo">Démonstration · Hébergements, disponibilités et tarifs fictifs · Aucune réservation réelle.</div>${staySearchForm()}<div class="travel-categories">${['Tous',...new Set(stayCatalog.map(p=>p.type))].map(t=>`<button aria-pressed="${staySearch.type===t}" onclick="staySearch.type='${t}';render()">${t}</button>`).join('')}</div><div class="sectiontitle"><h2>${list.length} habitats à explorer</h2><span class="smallnote">${nights(staySearch.arrival,staySearch.departure)} nuit(s) · ${staySearch.guests} voyageur(s)</span></div><div class="stay-grid">${stayCards(list)}</div><section class="panel travel-bottom"><h2>Un séjour, toute la vie du Domaine.</h2><p class="sub">Profitez du jardin, composez un panier au marché et explorez les alentours à vélo.</p><div class="travel-links"><a href="#velos">Réserver un vélo ↗</a><a href="#producteurs">Composer mon panier ↗</a><a href="#ville">Explorer le plan 3D ↗</a></div></section>`}
function stayDetail(id){const p=stayCatalog.find(p=>p.id===id),q=stayQuote(p,staySearch),available=stayUnit(p,staySearch)!==null;modal(`<div class="stay-detail-art">${p.id==='luxe'?'<img src="assets/maison-l-bois-reference.webp" alt="Maison en L avec terrasse">':habitatArt(p.art)}</div><div class="eyebrow">${p.type.toUpperCase()} · HÉBERGEMENT FICTIF</div><h2 style="margin-top:15px">${p.name}</h2><p>${p.desc}</p><div class="stay-amenities">${p.amenities.map(a=>`<span>${a}</span>`).join('')}</div><p>${displayDate(staySearch.arrival)} → ${displayDate(staySearch.departure)}<br>${staySearch.guests} voyageur(s) · capacité ${p.capacity}</p><div class="quote-row"><span>${money(p.night)} × ${q.nights} nuit(s)</span><b>${money(q.subtotal)}</b></div><div class="quote-row"><span>Préparation du logement · forfait fictif</span><b>${money(q.fee)}</b></div><div class="quote-row quote-total"><span>Total de démonstration</span><b>${money(q.total)}</b></div><p class="smallnote">Montants de scénario uniquement, sans paiement, taxe réelle ou engagement. Annulation libre dans la démo.</p>${available?`<button class="btn" onclick="confirmStay('${p.id}')">Confirmer la réservation fictive</button>`:'<div class="notice">Ce logement est complet pour ces dates ou sa capacité est insuffisante. Modifiez votre recherche.</div>'}<button class="textlink" style="display:block;margin-top:15px" onclick="document.getElementById('modal').close();location.hash='#sejours'">Modifier mes dates et voyageurs ↗</button>${p.id==='luxe'?'<a class="textlink" href="#domaine" onclick="document.getElementById(\'modal\').close()">Visiter la maison en 3D ↗</a>':''}`)}
function confirmStay(id){const p=stayCatalog.find(p=>p.id===id),unit=stayUnit(p,staySearch);if(!unit){toast('Ce logement n’est plus disponible pour vos critères.');return}const q=stayQuote(p,staySearch),b={id:travelId('SEJ'),habitat:id,unit,arrival:staySearch.arrival,departure:staySearch.departure,guests:staySearch.guests,total:q.total,status:'confirme',created:nowDate()};state.staysV7.unshift(b);save();$('#modal').close();render();modal(`<div class="eyebrow">RÉSERVATION FICTIVE CONFIRMÉE</div><h2 style="margin-top:15px">Votre escapade prend forme.</h2><p>${p.name} · habitat ${unit}<br>${displayDate(b.arrival)} → ${displayDate(b.departure)}<br>${b.guests} voyageur(s) · ${money(b.total)} fictifs</p><p>Référence : <b>${b.id}</b></p><div class="notice">Cette réservation reste dans ce navigateur. Aucun hébergeur n’est contacté, aucun paiement effectué.</div><button class="btn" onclick="document.getElementById('modal').close();location.hash='#reservations'">Voir ma réservation</button>`)}
const timeMinutes=s=>/^\d{2}:\d{2}$/.test(s)?Number(s.slice(0,2))*60+Number(s.slice(3)):NaN;
function bikeError(s){if(!dateValid(s.date)||s.date<nowDate())return 'Choisissez une date à partir d’aujourd’hui.';let a=timeMinutes(s.start),b=timeMinutes(s.end);if(!Number.isFinite(a)||!Number.isFinite(b)||a<480||b>1200||b<=a||b-a>480||a%30||b%30)return 'Choisissez un créneau entre 08 h et 20 h, par demi-heures, de 30 minutes à 8 heures.';return ''}
function bikeUnit(p,s){travelInit();if(bikeError(s))return null;for(let u=1;u<=p.count;u++)if(!state.bikesV7.some(b=>b.bike===p.id&&b.unit===u&&!['annule','rendu'].includes(b.status)&&b.date===s.date&&overlaps(timeMinutes(s.start),timeMinutes(s.end),timeMinutes(b.start),timeMinutes(b.end))))return u;return null}
function bikeQuote(p,s){return Math.round((timeMinutes(s.end)-timeMinutes(s.start))/60*p.rate*100)/100}
function bikeView(){travelInit();return heading('Le Domaine à vélo.','Choisissez votre vélo et un créneau, puis simulez le départ et le retour.',`<a class="btn light" href="#reservations">Mes réservations ↗</a>`)+`<div class="travel-demo">Flotte fictive de 6 vélos · Casque et antivol inclus dans le scénario · Disponibilités locales à ce navigateur.</div><form class="travel-search" onsubmit="event.preventDefault();searchBikes(this)"><div><label for="bike-date">Date</label><input id="bike-date" name="date" type="date" min="${nowDate()}" required value="${bikeSearch.date}"></div><div><label for="bike-start">Départ</label><input id="bike-start" name="start" type="time" min="08:00" max="19:30" step="1800" required value="${bikeSearch.start}"></div><div><label for="bike-end">Retour</label><input id="bike-end" name="end" type="time" min="08:30" max="20:00" step="1800" required value="${bikeSearch.end}"></div><button class="btn">Voir les disponibilités ↗</button></form><p class="smallnote">Ouverture de démonstration : 08 h – 20 h · Réservation de 30 min à 8 h · Aucun prélèvement.</p><div class="bike-grid">${bikeCatalog.map(p=>{const u=bikeUnit(p,bikeSearch),q=bikeQuote(p,bikeSearch);return `<article class="stay-card"><div class="bike-art">${bikeArt(p.id)}</div><div class="stay-body"><small>${p.count} vélo(s) dans la flotte fictive</small><h3>${p.name}</h3><p>${p.desc}</p><div class="stay-price"><div><b>${money(p.rate)}</b><small> / heure fictive</small><span class="${u?'available':'unavailable'}">${u?'Disponible':'Complet sur ce créneau'}</span></div><button class="btn light" ${u?'':'disabled'} onclick="bikeDetail('${p.id}')">Réserver · ${money(q)}</button></div></div></article>`}).join('')}</div><section class="panel"><h2>Comment ça marche ?</h2><div class="grid3" style="margin-top:20px">${[['01 · Réserver','Une date et un créneau. Chaque vélo est attribué individuellement.'],['02 · Partir','Retrouvez le vélo au point mobilité. La prise en charge est simulée depuis vos réservations.'],['03 · Rendre','Simulez le retour pour libérer le vélo. Casque, antivol et état du vélo sont à vérifier dans une version réelle.']].map(x=>`<div><h3>${x[0]}</h3><p class="sub">${x[1]}</p></div>`).join('')}</div></section>`}
function searchBikes(f){let s={date:f.date.value,start:f.start.value,end:f.end.value};const err=bikeError(s);if(err){toast(err);return}bikeSearch=s;render()}
function bikeDetail(id){const p=bikeCatalog.find(p=>p.id===id),u=bikeUnit(p,bikeSearch);if(!u){toast('Aucun vélo de ce type disponible sur le créneau.');return}modal(`<div class="bike-art">${bikeArt(p.id)}</div><h2>${p.name} · n° ${u}</h2><p>${displayDate(bikeSearch.date)} · ${bikeSearch.start} – ${bikeSearch.end}<br>Retrait et retour au point mobilité.</p><div class="quote-row"><span>Durée</span><b>${(timeMinutes(bikeSearch.end)-timeMinutes(bikeSearch.start))/60} h</b></div><div class="quote-row quote-total"><span>Montant fictif</span><b>${money(bikeQuote(p,bikeSearch))}</b></div><p class="smallnote">Casque et antivol inclus dans le scénario. Aucun dépôt de garantie, paiement ou location réelle.</p><button class="btn" onclick="confirmBike('${id}')">Confirmer le vélo fictif</button>`)}
function confirmBike(id){let p=bikeCatalog.find(p=>p.id===id),unit=bikeUnit(p,bikeSearch);if(!unit){toast('Vélo indisponible. Recherchez un autre créneau.');return}state.bikesV7.unshift({id:travelId('VELO'),bike:id,unit,...bikeSearch,total:bikeQuote(p,bikeSearch),status:'reserve',created:nowDate()});save();$('#modal').close();location.hash='#reservations';render();toast('Vélo réservé dans la démonstration.')}
function reservationView(){travelInit();return heading('Vos prochaines escapades.','Séjours et vélos réunis, avec un suivi et une annulation dans la démo.',`<a class="btn" href="#sejours">Choisir un séjour ↗</a>`)+`<div class="travel-demo">Ces réservations restent enregistrées sur cet appareil. Elles ne sont pas synchronisées entre visiteurs.</div><div class="sectiontitle"><h2>Mes séjours</h2><a class="textlink" href="#sejours">Découvrir les habitats ↗</a></div>${state.staysV7.map(b=>{let p=stayCatalog.find(p=>p.id===b.habitat);return `<article class="booking-card"><div><span class="booking-status ${b.status==='annule'?'muted':''}">${b.status==='annule'?'Annulé':'Confirmé · démo'}</span><h3>${p.name} · habitat ${b.unit}</h3><p>${displayDate(b.arrival)} → ${displayDate(b.departure)} · ${b.guests} voyageur(s)<br>${b.id} · ${money(b.total)} fictifs</p></div><div class="booking-actions">${b.status!=='annule'?`<button class="btn light" onclick="cancelTravelForm('stay','${b.id}')">Annuler le séjour</button><a class="textlink" href="#velos">Ajouter un vélo ↗</a>`:''}</div></article>`}).join('')||'<section class="panel empty">Aucun séjour réservé. Découvrez les cabanes, containers et maisons du Domaine.</section>'}<div class="sectiontitle"><h2>Mes vélos</h2><a class="textlink" href="#velos">Choisir un vélo ↗</a></div>${state.bikesV7.map(b=>{let p=bikeCatalog.find(p=>p.id===b.bike);return `<article class="booking-card"><div><span class="booking-status ${['annule','rendu'].includes(b.status)?'muted':''}">${{reserve:'Réservé · démo',sorti:'En balade · démo',rendu:'Retourné · démo',annule:'Annulé'}[b.status]}</span><h3>${p.name} · n° ${b.unit}</h3><p>${displayDate(b.date)} · ${b.start} – ${b.end}<br>${b.id} · ${money(b.total)} fictifs</p></div><div class="booking-actions">${b.status==='reserve'?`<button class="btn" onclick="bikeLifecycle('${b.id}','sorti')">Simuler la prise en charge</button><button class="textlink" onclick="cancelTravelForm('bike','${b.id}')">Annuler</button>`:b.status==='sorti'?`<button class="btn" onclick="bikeLifecycle('${b.id}','rendu')">Simuler le retour</button>`:''}</div></article>`}).join('')||'<section class="panel empty">Aucun vélo réservé. Choisissez un modèle et un créneau pour essayer.</section>'}<p class="smallnote">Pour modifier des dates, annulez la réservation puis effectuez une nouvelle recherche. L’historique reste visible.</p>`}
function cancelTravelForm(type,id){modal(`<h2>Annuler cette réservation fictive ?</h2><p>Le créneau ou le logement sera libéré dans la démonstration. La réservation restera visible dans votre historique.</p><button class="btn" onclick="cancelTravel('${type}','${id}')">Confirmer l’annulation</button><button class="btn light" style="margin-left:8px" onclick="document.getElementById('modal').close()">La conserver</button>`)}
function cancelTravel(type,id){let b=(type==='stay'?state.staysV7:state.bikesV7).find(b=>b.id===id);if(!b)return;b.status='annule';save();$('#modal').close();render();toast('Réservation annulée. Disponibilité libérée.')}
function bikeLifecycle(id,next){const b=state.bikesV7.find(b=>b.id===id);if(!b||!((b.status==='reserve'&&next==='sorti')||(b.status==='sorti'&&next==='rendu')))return;b.status=next;save();render();toast(next==='sorti'?'Prise en charge simulée. Bonne balade !':'Retour simulé. Le vélo est de nouveau disponible.')}
function welcomeView(){travelInit();return `<section class="welcome-hero"><img src="assets/maison-l-bois-reference.webp" alt="La maison en L du Domaine, sa terrasse et son jardin"><div class="welcome-shade"></div><div class="welcome-copy"><div class="eyebrow">LE DOMAINE · YIN & YANG</div><h1>Quelques jours ailleurs.<br>Une autre façon de vivre.</h1><p>Cabanes, maisons en bois et containers ouverts sur la nature.<br>Venez habiter, explorer et partager.</p><a class="btn" href="#sejours">Trouver mon habitat ↗</a><a class="welcome-tour" href="#ville">Visiter le Domaine en 3D →</a></div><span class="welcome-label">CONCEPT DE SÉJOUR · DÉMONSTRATION</span></section>${staySearchForm()}<div class="welcome-shortcuts"><a href="#sejours"><b>⌂ Séjourner</b><span>6 styles d’habitats</span></a><a href="#velos"><b>↗ Explorer à vélo</b><span>6 vélos à réserver</span></a><a href="#producteurs"><b>♧ Bien manger</b><span>La marketplace du Domaine</span></a><a href="#reservations"><b>▤ Mes réservations</b><span>Retrouver mes essais</span></a></div><div class="sectiontitle"><div><div class="eyebrow">VOTRE PARENTHÈSE AU VERT</div><h2 style="font-size:25px;margin-top:10px">À chacun son refuge.</h2></div><a class="textlink" href="#sejours">Tous les habitats ↗</a></div><div class="stay-grid">${stayCards([stayCatalog[0],stayCatalog[1],stayCatalog[2]])}</div><section class="welcome-story"><div>${domainEmblem()}<h2>Plus qu’un lieu.<br>Un Domaine à vivre.</h2><p>Un potager à observer, des producteurs à découvrir, un vélo pour s’échapper et une place commune pour se rencontrer.</p><div class="travel-links"><a href="#domaine">La maison en L ↗</a><a href="#jardin">Le potager ↗</a><a href="#communaute">La vie commune ↗</a></div></div><div>${domainPlan()}</div></section><div class="travel-demo">Présentation interactive : prix, habitats, disponibilités et réservations fictifs, conservés uniquement dans ce navigateur. Aucun paiement.</div>`}
// L'ancien tableau de bord demeure disponible dans l'espace résident.
views.resident=views.accueil;routes[0]=['accueil','⌂','Accueil du Domaine'];routes.splice(1,0,['sejours','⌂','Nos habitats'],['velos','↗','Location de vélos'],['reservations','▤','Mes réservations']);routes.push(['resident','◎','Espace résident']);views.accueil=welcomeView;views.sejours=staysView;views.velos=bikeView;views.reservations=reservationView;
const reserveBeforeTravel=reserve;reserve=function(name){if(/vélo/i.test(name)){location.hash='#velos';return}reserveBeforeTravel(name)};
const cityActionBeforeTravel=cityAction;cityAction=function(id){if(id==='mobilite'){location.hash='#velos';return}cityActionBeforeTravel(id)};
cityPlaces.find(p=>p.id==='mobilite').action='Choisir et réserver un vélo';cityPlaces.find(p=>p.id==='mobilite').detail='Vélos de ville, VTT, électrique et cargo : disponibilités par créneau, annulation et suivi du retour dans la démonstration.';
const resetBeforeTravel=resetDemo;resetDemo=function(){resetBeforeTravel();state.staysV7=[];state.bikesV7=[];save();render()};
slides.splice(2,0,{k:'SÉJOURNER AU DOMAINE',title:'Un habitat pour chaque envie.',text:'Choisir une cabane, un container ou une maison en L. Composer son séjour, explorer le village et réserver un vélo depuis un accueil commun.',cards:[['Séjourner','Six types d’habitats, des dates et un nombre de voyageurs.'],['Explorer','Six vélos fictifs : ville, VTT, électrique et cargo.'],['Retrouver','Un suivi local des réservations, des annulations et du retour des vélos.']]});slides.forEach((s,i)=>s.k=String(i+1).padStart(2,'0')+' · '+s.k.replace(/^\d+ · /,''));
render();
